import json
import subprocess
import sys
import re

def run_recipe(recipe_path):
    with open(recipe_path) as f:
        recipe = json.load(f)

    vars_dict = recipe["vars"]
    steps = recipe["steps"]
    output = {}
    step_outputs = {}

    for step in steps:
        step_name = step["name"]
        command = step["command"]

        # Replace variables in command
        for var_name in vars_dict:
            if f"{{{{{var_name}}}}}" in command:
                command = command.replace(f"{{{{{var_name}}}}}", str(vars_dict[var_name]))

        # Replace step outputs
        for existing_name in step_outputs:
