import json
import sys
import subprocess
import re

def resolve_expr(expr, vars_dict, steps_dict):
    def replace_match(match):
        expr_name = match.group(1).strip()
        if expr_name == 'steps':
            return steps_dict.get(expr_name, '')
        return str(vars_dict.get(expr_name, ''))

    return re.sub(r'\{\{([^}]+)\}\}', replace_match, expr)

def run_recipe(recipe_path):
    with open(recipe_path, 'r') as f:
        recipe = json.load(f)

    vars_dict = recipe['vars']
    steps_list = recipe['steps']
    steps_dict = {}

    for step in steps_list:
        command = resolve_expr(step['command'], vars_dict, steps_dict)
        result = subprocess.run(command, shell=True, check=False, text=True, capture_output=True)
        if result.returncode != 0:
            sys.exit(result.returncode)
        steps_dict[step['name']] = result.stdout.rstrip('\n')

    output = json.dumps({step['name']: steps_dict[step['name']] for step in steps_list}, indent=0)
    print(output)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(1)
