import json
import sys
import subprocess
import re
from collections import OrderedDict

def expand_command(command, vars_dict, steps_dict):
    def replace_placeholder(match):
        expr = match.group(1).strip()
        if expr == 'steps':
            return json.dumps(steps_dict, separators=(',', ':'))
        elif expr in vars_dict:
            value = vars_dict[expr]
            if isinstance(value, int):
                return str(value)
            return str(value)
        return match.group(0)

    # Handle braces with optional spaces
    pattern = re.compile(r'\{\{([^}]+)\}\}')
    expanded = pattern.sub(replace_placeholder, command)
    return expanded

