import json
import sys
import subprocess
import re
from collections import OrderedDict

def expand_command(command, vars_dict, steps_dict):
    # Replace placeholders in the command
    def replace_match(match):
        expr = match.group(1)
        try:
            # Evaluate the expression with available variables
            if expr.startswith("steps['") and expr.endswith('']"):
                step_name = expr[7:-2]
                if step_name in steps_dict:
                    return steps_dict[step_name].rstrip('\n')
            else:
                # Handle other expressions (vars and steps)
                if expr in vars_dict:
                    return str(vars_dict[expr])
                elif expr == "steps":
                    return json.dumps(steps_dict, separators=(',', ':'))
                else:
                    raise ValueError(f"Unknown variable or expression: {expr}")
        except Exception:
            return match.group(0)  # Return original if evaluation fails

    # Use regex to find all placeholders
    pattern = re.compile(r'\{\{([^}]+)\}\}')
    expanded = pattern.sub(replace_match, command)
    return expanded

def run_recipe(recipe_path):
    with open(recipe_path, 'r') as f:
        recipe = json.load(f)

    vars_dict = recipe['vars']
    steps = recipe['steps']
    output_steps = OrderedDict()
    steps_dict = {}

    for step in steps:
        name = step['name']
        command = expand_command(step['command'], vars_dict, steps_dict)

        try:
            result = subprocess.run(
                command,
                shell=True,
                check=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True
            )
            output = result.stdout.rstrip('\n')
            output_steps[name] = output
            steps_dict[name] = output
        except subprocess.CalledProcessError as e:
            sys.exit(e.returncode)

    if output_steps:
        output = json.dumps(
            dict(output_steps),
            separators=(',', ': ')
        )
        print(output)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(1)
    run_recipe(sys.argv[1])
